from docx import Document
p=r"C:/Users/SALEADMIN/Downloads/Briefpapier Kopf Fußzeile Vorlage.docx"
d=Document(p)
s=d.sections[0]
for nm,part in (("HEADER",s.header),("FIRST-PAGE HEADER",s.first_page_header),("EVEN HEADER",s.even_page_header),("FOOTER",s.footer),("FIRST-PAGE FOOTER",s.first_page_footer)):
    try:
        print(f"--- {nm} linked={part.is_linked_to_previous} paras={len(part.paragraphs)} tables={len(part.tables)}")
        for pa in part.paragraphs:
            if pa.text.strip() or pa.runs:
                imgs=pa._p.xml.count('<pic:pic')
                print(f"    text={pa.text[:100]!r} imgs={imgs} align={pa.alignment}")
        for t in part.tables:
            for row in t.rows:
                print("    ROW:", [c.text.strip()[:40] for c in row.cells])
    except Exception as e:
        print(nm, "ERR", e)
print("=== STYLES ===")
for st in d.styles:
    try:
        if st.type is not None: print(" ", st.type, "|", st.name)
    except: pass
EOF

